    38→  | "ideas"
    39→  | "agent"
    40→  | "files"
    41→  | "github"
    42→  | "chat-monitor";
    43→
    44→export type SettingsSection =
    45→  | "general"
    46→  | "account"
    47→  | "shortcuts"
    48→  | "notifications"
    49→  | "gateway"
    50→  | "channels"
